from fastapi import APIRouter, Depends, HTTPException
from sqlalchemy.ext.asyncio import AsyncSession
from sqlalchemy import event

router = APIRouter(prefix="/admin/settings")

def publish_audit_events_after_commit(session):
    for obj in session.identity_map.values():
        if isinstance(obj, TenantPreference) and getattr(obj, "_modified_by_tenant", None) == obj.tenant_id:
            WebhookNotificationClient.fire_for_tenant(obj.tenant_id, obj.to_dict())

@router.put("/preferences")
async def update_tenant_preference(
    payload: PreferenceUpdateRequest,
    db: AsyncSession = Depends(get_async_session),
    user: TenantAdmin = Depends(get_tenant_admin)
):
    pref = await db.get(TenantPreference, user.tenant_id)
    if not pref:
        raise HTTPException(status_code=404, detail="Preference record not found")

    pref.theme_config = payload.theme
    pref.internal_notes = payload.notes
    pref._modified_by_tenant = user.tenant_id
    await db.commit()
    return {"status": "saved"}
